<?php

declare(strict_types=1);

/**
 * Fetch all Google Fonts families from the public metadata endpoint and write
 * a PHP lookup file that FontResolver::googleFonts() can require at runtime.
 *
 * Usage:
 *   php figma-transformer/scripts/generate-google-fonts.php
 *
 * Output:
 *   figma-transformer/src/Html/generated/google-fonts.php
 */

$endpointUrl = 'https://fonts.google.com/metadata/fonts';
$outputFile  = __DIR__ . '/../src/Html/generated/google-fonts.php';

// ---------------------------------------------------------------------------
// 1. Fetch the metadata JSON.
// ---------------------------------------------------------------------------

$json = false;

if ( function_exists('curl_init') ) {
    $ch = curl_init($endpointUrl);
    if ( false !== $ch ) {
        curl_setopt_array($ch, array(
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_TIMEOUT        => 30,
            CURLOPT_USERAGENT      => 'figma-transformer/generate-google-fonts (+https://github.com/Automattic/blocks-engine)',
            CURLOPT_HTTPHEADER     => array('Accept: application/json'),
        ));
        $json     = curl_exec($ch);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        $curlErr  = curl_error($ch);
        // curl_close() is intentionally omitted — it has been a no-op since PHP 8.0
        // and is deprecated in PHP 8.5+.

        if ( false === $json || '' === $json ) {
            fwrite(STDERR, "ERROR: curl fetch failed: {$curlErr}\n");
            exit(1);
        }
        if ( $httpCode < 200 || $httpCode >= 300 ) {
            fwrite(STDERR, "ERROR: HTTP {$httpCode} from {$endpointUrl}\n");
            exit(1);
        }
    }
}

if ( false === $json ) {
    // Fall back to file_get_contents if curl is unavailable.
    $context = stream_context_create(array(
        'http' => array(
            'method'  => 'GET',
            'timeout' => 30,
            'header'  => implode("\r\n", array(
                'User-Agent: figma-transformer/generate-google-fonts (+https://github.com/Automattic/blocks-engine)',
                'Accept: application/json',
            )),
        ),
    ));

    $json = @file_get_contents($endpointUrl, false, $context);

    if ( false === $json ) {
        fwrite(STDERR, "ERROR: Failed to fetch {$endpointUrl} via file_get_contents. Check your network connection.\n");
        exit(1);
    }
}

// The Google Fonts endpoint wraps the response in ")]}'\n" as an XSSI guard.
$json = preg_replace('/^\)\]\}\'\\s*/', '', $json);

// ---------------------------------------------------------------------------
// 2. Parse JSON and extract family list.
// ---------------------------------------------------------------------------

$data = json_decode((string) $json, true, 512, JSON_THROW_ON_ERROR);

if ( ! is_array($data) || ! isset($data['familyMetadataList']) || ! is_array($data['familyMetadataList']) ) {
    fwrite(STDERR, "ERROR: Unexpected JSON structure — 'familyMetadataList' key not found.\n");
    fwrite(STDERR, "Keys found: " . implode(', ', array_keys($data ?? array())) . "\n");
    exit(1);
}

// ---------------------------------------------------------------------------
// 3. Map categories to CSS generics.
// ---------------------------------------------------------------------------

$categoryMap = array(
    'SANS_SERIF' => 'sans-serif',
    'SERIF'      => 'serif',
    'MONOSPACE'  => 'monospace',
    'DISPLAY'    => 'sans-serif',
    'HANDWRITING' => 'sans-serif',
);

$fonts = array();

foreach ( $data['familyMetadataList'] as $item ) {
    if ( ! is_array($item) || ! isset($item['family']) || ! is_string($item['family']) ) {
        continue;
    }

    $family   = $item['family'];
    $category = isset($item['category']) && is_string($item['category']) ? $item['category'] : '';
    $generic  = $categoryMap[$category] ?? 'sans-serif';
    $key      = strtolower($family);

    $fonts[$key] = array('family' => $family, 'generic' => $generic);
}

if ( empty($fonts) ) {
    fwrite(STDERR, "ERROR: No font families found in the metadata response.\n");
    exit(1);
}

// Sort by lowercased key (ascending).
ksort($fonts, SORT_STRING | SORT_FLAG_CASE);

// ---------------------------------------------------------------------------
// 4. Generate PHP source.
// ---------------------------------------------------------------------------

// Measure the longest key to align value columns (cap at 32 chars).
$maxKeyLen = 0;
foreach ( array_keys($fonts) as $key ) {
    $len = strlen($key);
    if ( $len > $maxKeyLen ) {
        $maxKeyLen = $len;
    }
}
$padWidth = min($maxKeyLen, 32);

$lines   = array();
$lines[] = '<?php';
$lines[] = '// Generated by scripts/generate-google-fonts.php — do not edit manually.';
$lines[] = '// Regenerate: php figma-transformer/scripts/generate-google-fonts.php';
$lines[] = 'return array(';

$count = count($fonts);
$i     = 0;
foreach ( $fonts as $key => $entry ) {
    $i++;
    $comma   = ( $i < $count ) ? ',' : '';
    $family  = addslashes($entry['family']);
    $generic = $entry['generic'];
    // Pad the quoted-key token so value columns align, e.g. 'abel'  =>  vs 'jetbrains mono'  =>
    // The token is "'" + key + "'", so its natural width is strlen($key)+2.
    $quotedKey        = "'" . $key . "'";
    $quotedKeyPadded  = str_pad($quotedKey, $padWidth + 2);
    $lines[]          = "    {$quotedKeyPadded} => array('family' => '{$family}', 'generic' => '{$generic}'){$comma}";
}

$lines[] = ');';

$source = implode("\n", $lines) . "\n";

// ---------------------------------------------------------------------------
// 5. Write output file.
// ---------------------------------------------------------------------------

$dir = dirname($outputFile);
if ( ! is_dir($dir) ) {
    if ( ! mkdir($dir, 0755, true) ) {
        fwrite(STDERR, "ERROR: Could not create directory {$dir}\n");
        exit(1);
    }
}

if ( file_put_contents($outputFile, $source) === false ) {
    fwrite(STDERR, "ERROR: Could not write {$outputFile}\n");
    exit(1);
}

echo "Wrote {$count} font families to {$outputFile}\n";
